import { InjectionToken, InjectOptions, InputSignal, isSignal, Type } from '@angular/core';
import { LinkedList } from '@abp/utils';
import { ePropType } from '../enums/props.enum';
import { FormPropTooltip } from './form-props';

export abstract class PropList<R = any, A = Prop<R>> extends LinkedList<A> {}

export abstract class PropData<R = any> {
  abstract getInjected: <T>(
    token: Type<T> | InjectionToken<T>,
    notFoundValue?: T,
    options?: InjectOptions,
  ) => T;
  index?: number | InputSignal<number | undefined>;
  abstract record: R | InputSignal<R>;

  get data(): ReadonlyPropData<R> {
    return {
      getInjected: this.getInjected,
      // `record` / `index` may be signals; always use `data.record` / `data.index`.
      index: isSignal(this.index) ? this.index() : this.index,
      record: isSignal(this.record) ? this.record() : this.record,
    };
  }
}

export type ReadonlyPropData<R = any> = Readonly<{
  getInjected: <T>(
    token: Type<T> | InjectionToken<T>,
    notFoundValue?: T,
    options?: InjectOptions,
  ) => T;
  index?: number;
  record: R;
}>;

export abstract class Prop<R = any> {
  constructor(
    public readonly type: ePropType,
    public readonly name: string,
    public readonly displayName: string,
    public readonly permission: string,
    public readonly visible: PropPredicate<R> = _ => true,
    public readonly isExtra = false,
    public readonly template?: Type<any>,
    public readonly className?: string,
    public readonly formText?: string,
    public readonly tooltip?: FormPropTooltip,
    public readonly displayTextResolver?: PropDisplayTextResolver<R>,
  ) {
    this.displayName = this.displayName || this.name;
  }
}

export type PropCallback<T, R = any> = (data: ReadonlyPropData<T>, auxData?: any) => R;
export type PropPredicate<T> = (data?: ReadonlyPropData<T>, auxData?: any) => boolean;
export type PropDisplayTextResolver<T> = (data?: ReadonlyPropData<T>) => string;

export abstract class PropsFactory<C extends Props<any>> {
  protected abstract _ctor: Type<C>;
  private contributorCallbacks: PropContributorCallbacks<InferredPropList<C>> = {};

  get(name: string): C {
    this.contributorCallbacks[name] = this.contributorCallbacks[name] || [];

    return new this._ctor(this.contributorCallbacks[name]);
  }
}

export abstract class Props<L extends PropList<any, InferredProp<L>>> {
  protected abstract _ctor: Type<L>;

  get props(): L {
    const propList = new this._ctor();

    this.callbackList.forEach(callback => callback(propList));

    return propList;
  }

  constructor(private readonly callbackList: PropContributorCallback<L>[]) {}

  addContributor(contributeCallback: PropContributorCallback<L>) {
    this.callbackList.push(contributeCallback);
  }

  clearContributors() {
    while (this.callbackList.length) this.callbackList.pop();
  }
}

export type PropContributorCallbacks<L extends PropList<any, InferredProp<L>>> = Record<
  string,
  PropContributorCallback<L>[]
>;

export type PropContributorCallback<L extends PropList<any, InferredProp<L>>> = (
  propList: L,
) => any;

type InferredPropList<C> = C extends Props<infer L> ? L : never;
export type InferredProp<T> = T extends PropList<any, infer U> ? U : T;
